import{_ as n,o as h,c as e,a4 as i}from"./chunks/framework.CRKgIIuH.js";const d=JSON.parse('{"title":"ĐỀ CƯƠNG KHÓA HỌC MỞ MIỄN PHÍ — TỰ HỌC THEO NHỊP","description":"","frontmatter":{},"headers":[],"relativePath":"course/book/syllabus.md","filePath":"course/book/syllabus.md"}'),a={name:"course/book/syllabus.md"};function l(c,t,o,g,r,s){return h(),e("div",null,[...t[0]||(t[0]=[i(`<blockquote><p><strong>Lưu ý hiển thị:</strong> sơ đồ Mermaid và/hoặc công thức được giữ nguyên dạng mã vì VitePress hiện chưa cấu hình renderer tương ứng.</p></blockquote><h1 id="đe-cuong-khoa-hoc-mo-mien-phi-—-tu-hoc-theo-nhip" tabindex="-1">ĐỀ CƯƠNG KHÓA HỌC MỞ MIỄN PHÍ — TỰ HỌC THEO NHỊP <a class="header-anchor" href="#đe-cuong-khoa-hoc-mo-mien-phi-—-tu-hoc-theo-nhip" aria-label="Permalink to &quot;ĐỀ CƯƠNG KHÓA HỌC MỞ MIỄN PHÍ — TỰ HỌC THEO NHỊP&quot;">​</a></h1><h2 id="quan-ly-du-lieu-nghien-cuu-y-sinh-biomedical-research-data-management" tabindex="-1">QUẢN LÝ DỮ LIỆU NGHIÊN CỨU Y SINH (BIOMEDICAL RESEARCH DATA MANAGEMENT) <a class="header-anchor" href="#quan-ly-du-lieu-nghien-cuu-y-sinh-biomedical-research-data-management" aria-label="Permalink to &quot;QUẢN LÝ DỮ LIỆU NGHIÊN CỨU Y SINH (BIOMEDICAL RESEARCH DATA MANAGEMENT)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Thuộc tính</th><th style="text-align:left;">Chi tiết</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Tên khóa học</strong></td><td style="text-align:left;">Quản lý dữ liệu nghiên cứu y sinh (Biomedical Research Data Management - BioRDM)</td></tr><tr><td style="text-align:left;"><strong>Hình thức</strong></td><td style="text-align:left;"><strong>Khóa học mở miễn phí, tự học theo nhịp người đọc (Free, Self-paced Online Course)</strong></td></tr><tr><td style="text-align:left;"><strong>Phiên bản đề cương</strong></td><td style="text-align:left;"><strong>v1.0.0_20261121 (Free &amp; Self-Paced Edition)</strong></td></tr><tr><td style="text-align:left;"><strong>Ngày chốt cập nhật</strong></td><td style="text-align:left;">21/11/2026</td></tr><tr><td style="text-align:left;"><strong>Tác giả / Thiết kế</strong></td><td style="text-align:left;"><strong>TS. Hoàng Quang Huy</strong> (Đại học Bách khoa Hà Nội, iBME Lab · ORCID: <a href="https://orcid.org/0000-0002-4603-1297" target="_blank" rel="noreferrer">0000-0002-4603-1297</a>)</td></tr><tr><td style="text-align:left;"><strong>Thời gian học gợi ý</strong></td><td style="text-align:left;"><strong>Khoảng 4–6 giờ đọc + quiz; khoảng 9–12 giờ nếu làm đủ các lab tự chọn và capstone</strong></td></tr><tr><td style="text-align:left;"><strong>Đối tượng học tập</strong></td><td style="text-align:left;">Sinh viên ngành Kỹ thuật Y sinh (BME), Công nghệ Thông tin Y tế, Khoa học Dữ liệu Y tế; Bác sĩ lâm sàng, Học viên Cao học, Nghiên cứu sinh Y Dược; Điều phối viên nghiên cứu lâm sàng (CRC/CRA). Không bắt buộc biết lập trình cho các bài đầu (Lab 5–6 có phần code Python/R mở rộng, có thể bỏ qua).</td></tr><tr><td style="text-align:left;"><strong>Quyền truy cập &amp; Bản quyền</strong></td><td style="text-align:left;">Hoàn toàn miễn phí, mở trực tiếp trên web, không cần đăng nhập, không thu thập dữ liệu cá nhân người học. Nội dung bài giảng phát hành theo giấy phép <strong>Creative Commons CC BY 4.0</strong>, mã nguồn thực hành theo giấy phép <strong>MIT License</strong>.</td></tr><tr><td style="text-align:left;"><strong>Trạng thái thư mục</strong></td><td style="text-align:left;"><code>references.bib</code> có 103 mục lõi và các mục riêng của chương (tổng 115 mục trong file hiện tại); trạng thái gồm <code>VERIFIED_UNAUDITED</code>/<code>BIB_PENDING</code>, chưa audit độc lập.</td></tr></tbody></table><hr><h2 id="_1-nguyen-tac-va-đac-điem-khoa-hoc" tabindex="-1">1. NGUYÊN TẮC VÀ ĐẶC ĐIỂM KHÓA HỌC <a class="header-anchor" href="#_1-nguyen-tac-va-đac-điem-khoa-hoc" aria-label="Permalink to &quot;1. NGUYÊN TẮC VÀ ĐẶC ĐIỂM KHÓA HỌC&quot;">​</a></h2><p>Khóa học được xây dựng theo triết lý: <strong>Người đọc mở ra là học được ngay, không cần đăng ký, không cần chờ ai chấm điểm, không bị khóa bài theo tuần. Mọi rào cản không phục vụ việc học đều được loại bỏ.</strong></p><table tabindex="0"><thead><tr><th style="text-align:left;">Khóa học này LÀ</th><th style="text-align:left;">Khóa học này KHÔNG PHẢI LÀ</th></tr></thead><tbody><tr><td style="text-align:left;">Khóa học mở, miễn phí, đọc trực tiếp trên trình duyệt</td><td style="text-align:left;">Không phải học phần đại học có điểm hoặc xếp loại (không có quy đổi học phần, không có 30 giờ chuẩn hành chính)</td></tr><tr><td style="text-align:left;">Tự học theo nhịp của người đọc (self-paced): không có deadline, không khóa bài theo tuần</td><td style="text-align:left;">Khóa học có lịch học cố định theo tuần, điểm danh hay bắt buộc tiến độ</td></tr><tr><td style="text-align:left;">Tự kiểm tra kiến thức: quiz có đáp án và giải thích chi tiết ngay, làm lại không giới hạn</td><td style="text-align:left;">Bài thi có giám thị, chấm điểm qua/trượt để tính GPA</td></tr><tr><td style="text-align:left;">Lab thực hành tự chọn, làm để hiểu sâu và nâng cao tay nghề, không tính điểm</td><td style="text-align:left;">Bài tập bắt buộc nộp để lấy điểm thành phần</td></tr><tr><td style="text-align:left;">Capstone là bài tập tự đánh giá cuối khóa theo checklist có sẵn</td><td style="text-align:left;">Đồ án bắt buộc nộp để bảo vệ trước hội đồng</td></tr><tr><td style="text-align:left;">Có trang &quot;Hoàn thành khóa học&quot; để người đọc tự đối chiếu tiến độ cá nhân</td><td style="text-align:left;">Chứng nhận có đơn vị pháp nhân cấp chứng chỉ hành nghề</td></tr></tbody></table><hr><h2 id="_2-khung-nang-luc-đau-ra-learning-outcomes" tabindex="-1">2. KHUNG NĂNG LỰC ĐẦU RA (LEARNING OUTCOMES) <a class="header-anchor" href="#_2-khung-nang-luc-đau-ra-learning-outcomes" aria-label="Permalink to &quot;2. KHUNG NĂNG LỰC ĐẦU RA (LEARNING OUTCOMES)&quot;">​</a></h2><p>Sau khi hoàn thành khóa học, người đọc có khả năng tự tin:</p><ul><li><strong>LO1 (Hiểu sâu vòng đời &amp; quy chuẩn):</strong> Giải thích được vòng đời 7 giai đoạn của dữ liệu y sinh, cơ chế khuếch đại lỗi từ thượng nguồn, các nguyên tắc thực hành lâm sàng tốt ALCOA+ và ICH E6(R3), nguyên tắc dữ liệu mở FAIR, và ranh giới chuyên biệt giữa các chuẩn dữ liệu CDISC SDTM, HL7 FHIR, OMOP CDM.</li><li><strong>LO2 (Xây dựng kế hoạch dữ liệu):</strong> Thiết kế được bản Kế hoạch Quản lý và Chia sẻ Dữ liệu (DMP/DMSP) theo mẫu NIH hiện hành (7 yếu tố) hoặc Horizon Europe, tham khảo <code>/course/book/appendices/funder-templates</code>; tự thiết kế được Biểu mẫu thu thập dữ liệu điện tử (eCRF) và Từ điển biến số trên hệ thống REDCap.</li><li><strong>LO3 (Đánh giá chất lượng &amp; Bảo mật):</strong> Đánh giá được chất lượng dữ liệu y tế theo khung 5 chiều (Weiskopf &amp; Weng) và công cụ OHDSI DQD; phân loại đúng cơ chế dữ liệu khuyết (MCAR, MAR, MNAR); áp dụng kỹ thuật khử định danh (HIPAA Safe Harbor, Date Shifting, k-anonymity) phù hợp với pháp luật Việt Nam hiện hành.</li><li><strong>LO4 (Đóng gói dữ liệu FAIR &amp; AI-ready):</strong> Tự đóng gói và công bố bộ dữ liệu nghiên cứu y sinh có định danh số vĩnh viễn (DOI) trên kho dữ liệu mở tin cậy (Zenodo); đánh giá mức độ sẵn sàng cho AI của bộ dữ liệu theo 7 tiêu chí NIH Bridge2AI.</li></ul><hr><h2 id="_3-cau-truc-va-lo-trinh-7-giai-đoan" tabindex="-1">3. CẤU TRÚC VÀ LỘ TRÌNH 7 GIAI ĐOẠN <a class="header-anchor" href="#_3-cau-truc-va-lo-trinh-7-giai-đoan" aria-label="Permalink to &quot;3. CẤU TRÚC VÀ LỘ TRÌNH 7 GIAI ĐOẠN&quot;">​</a></h2><p>Khóa học lấy xương sống là <strong>Workflow Quản trị Dữ liệu Y sinh 7 giai đoạn</strong>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Thiết kế &amp; DMP → 2. Thu thập (ALCOA+/EDC) → 3. Làm sạch &amp; Đánh giá chất lượng</span></span>
<span class="line"><span>→ 4. Chuẩn hóa (CDISC / FHIR / OMOP) → 5. FAIR &amp; Chia sẻ kho lưu trữ</span></span>
<span class="line"><span>→ 6. Bảo mật &amp; Pháp lý (Luật 91/2025/QH15) → 7. Kết thúc: Lưu trữ dài hạn &amp; Hủy an toàn</span></span></code></pre></div><h3 id="danh-muc-module-hoc-tap" tabindex="-1">Danh mục Module Học tập <a class="header-anchor" href="#danh-muc-module-hoc-tap" aria-label="Permalink to &quot;Danh mục Module Học tập&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Module</th><th style="text-align:left;">Tên Module</th><th style="text-align:left;">Trọng tâm nội dung lý thuyết</th><th style="text-align:left;">Lab thực hành tự chọn</th><th style="text-align:left;">Thời gian gợi ý</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>M0</strong></td><td style="text-align:left;"><strong>Bắt đầu ở đây (Getting Started)</strong></td><td style="text-align:left;">Hướng dẫn cách tự học; workflow 7 giai đoạn; đạo đức dữ liệu, CITI/DUA; dữ liệu thật vs dữ liệu tổng hợp; hướng dẫn làm quiz và lab.</td><td style="text-align:left;">Khởi tạo môi trường thực hành cá nhân (trình duyệt, Python cơ bản).</td><td style="text-align:left;">15 phút</td></tr><tr><td style="text-align:left;"><strong>M1</strong></td><td style="text-align:left;"><strong>Tổng quan RDM, Vòng đời &amp; Kế hoạch DMP</strong></td><td style="text-align:left;">Khủng hoảng khả năng tái lập; Vòng đời 7 giai đoạn; Bộ ba Protocol vs DMP vs CRF; Mô hình quản trị DAMA-DMBOK và 3 hồ sơ Data Steward; NIH DMSP và Horizon Europe.</td><td style="text-align:left;"><strong>Lab 1:</strong> Soạn thảo bản DMSP theo mẫu NIH hiện hành (7 yếu tố) hoặc Horizon Europe, tham khảo phụ lục mẫu.</td><td style="text-align:left;">Đọc + Quiz: 30–40 phút<br><em>(Lab: +45 phút)</em></td></tr><tr><td style="text-align:left;"><strong>M2</strong></td><td style="text-align:left;"><strong>Thu thập Dữ liệu Lâm sàng, ALCOA+ &amp; REDCap</strong></td><td style="text-align:left;">Nguyên tắc ALCOA+ và ALCOA++; ICH E6(R3); Giám sát dựa trên rủi ro (RBQM); Kiến trúc hệ thống EDC.</td><td style="text-align:left;"><strong>Lab 2:</strong> Thiết kế dự án eCRF và Data Dictionary trên REDCap.</td><td style="text-align:left;">Đọc + Quiz: 40–50 phút<br><em>(Lab: +45 phút)</em></td></tr><tr><td style="text-align:left;"><strong>M3</strong></td><td style="text-align:left;"><strong>Chuẩn hóa Dữ liệu: CDISC, FHIR &amp; OMOP CDM</strong></td><td style="text-align:left;">Ba chuẩn bổ trợ nhau: CDISC SDTM (nộp hồ sơ), HL7 FHIR (trao đổi liên thông), OMOP CDM (phân tích quần thể); SMART on FHIR; Từ vựng chuẩn SNOMED CT, LOINC, RxNorm.</td><td style="text-align:left;"><strong>Lab 3:</strong> Thao tác truy vấn dữ liệu Synthea FHIR và ánh xạ OMOP.</td><td style="text-align:left;">Đọc + Quiz: 35–45 phút<br><em>(Lab: +45 phút)</em></td></tr><tr><td style="text-align:left;"><strong>M4</strong></td><td style="text-align:left;"><strong>Đánh giá Chất lượng Dữ liệu &amp; Dữ liệu Khuyết</strong></td><td style="text-align:left;">Khung chất lượng 5 chiều (Weiskopf &amp; Weng); Khung xác minh Kahn; Phân loại khuyết Rubin (MCAR, MAR, MNAR); Quy tắc Sterne về Multiple Imputation.</td><td style="text-align:left;"><strong>Lab 4:</strong> Chạy kiểm thử chất lượng dữ liệu OHDSI DQD và xử lý dữ liệu khuyết.</td><td style="text-align:left;">Đọc + Quiz: 30–40 phút<br><em>(Lab: +45 phút)</em></td></tr><tr><td style="text-align:left;"><strong>M5</strong></td><td style="text-align:left;"><strong>Bảo mật Dữ liệu, Khử định danh &amp; Pháp lý</strong></td><td style="text-align:left;">Luật Bảo vệ dữ liệu cá nhân 91/2025/QH15, Nghị định 356/2025/NĐ-CP; Thông tư 13/2025/TT-BYT; GDPR &amp; EHDS; HIPAA Safe Harbor vs Date Shifting; Mô hình k-anonymity và l-diversity.</td><td style="text-align:left;"><strong>Lab 5:</strong> Viết script khử định danh dữ liệu y tế (Python/R) tuân thủ HIPAA.</td><td style="text-align:left;">Đọc + Quiz: 40–50 phút<br><em>(Lab: +60 phút)</em></td></tr><tr><td style="text-align:left;"><strong>M6</strong></td><td style="text-align:left;"><strong>Nguyên tắc FAIR, Kho Lưu trữ &amp; Dữ liệu AI-Ready</strong></td><td style="text-align:left;">4 nguyên tắc FAIR; Quy trình FAIRification 7 bước; Kho lưu trữ mở (Zenodo, PhysioNet) vs có kiểm soát (dbGaP); 7 tiêu chí NIH Bridge2AI cho dữ liệu học máy.</td><td style="text-align:left;"><strong>Lab 6:</strong> Đóng gói bộ dữ liệu nghiên cứu và cấp DOI thử nghiệm trên Zenodo Sandbox.</td><td style="text-align:left;">Đọc + Quiz: 40–50 phút<br><em>(Lab: +45 phút)</em></td></tr><tr><td style="text-align:left;"><strong>Cuối khóa</strong></td><td style="text-align:left;"><strong>Quiz Tổng hợp Workflow &amp; Bài tập Capstone Tự đánh giá</strong></td><td style="text-align:left;">10 câu hỏi trắc nghiệm tổng hợp toàn bộ quy trình; Bài tập Capstone tự làm theo checklist; Trang đối chiếu hoàn thành khóa học.</td><td style="text-align:left;"><strong>Capstone:</strong> Soạn trọn gói hồ sơ RDM cho một nghiên cứu lâm sàng giả định.</td><td style="text-align:left;">45–60 phút</td></tr></tbody></table><hr><p><em>Ghi chú cách tính thời gian:</em> Chương 1–6 và các phụ lục hiện có khoảng 38.300 từ; ở tốc độ đọc văn bản kỹ thuật 150–200 từ/phút là khoảng 192–256 phút, cộng thời gian làm quiz. Dải 4–6 giờ là đọc + quiz; dải 9–12 giờ cộng lab tự chọn và capstone. Lab 1–4, 6 ước tính khoảng 45 phút/bài; Lab 5 khoảng 60 phút; capstone khoảng 45–60 phút.</p><h2 id="_4-co-che-đanh-gia-tu-đoi-chieu-khong-cham-điem" tabindex="-1">4. CƠ CHẾ ĐÁNH GIÁ: TỰ ĐỐI CHIẾU, KHÔNG CHẤM ĐIỂM <a class="header-anchor" href="#_4-co-che-đanh-gia-tu-đoi-chieu-khong-cham-điem" aria-label="Permalink to &quot;4. CƠ CHẾ ĐÁNH GIÁ: TỰ ĐỐI CHIẾU, KHÔNG CHẤM ĐIỂM&quot;">​</a></h2><p>Khóa học không sử dụng thang điểm số, điểm chữ hay xếp loại học lực. Người học hoàn toàn làm chủ tiến trình tự đánh giá năng lực của mình theo quy tắc sau:</p><h3 id="_4-1-he-thong-34-cau-hoi-tu-kiem-tra-self-check-quizzes" tabindex="-1">4.1. Hệ thống 34 Câu hỏi Tự kiểm tra (Self-Check Quizzes) <a class="header-anchor" href="#_4-1-he-thong-34-cau-hoi-tu-kiem-tra-self-check-quizzes" aria-label="Permalink to &quot;4.1. Hệ thống 34 Câu hỏi Tự kiểm tra (Self-Check Quizzes)&quot;">​</a></h3><ul><li><strong>24 câu hỏi theo từng bài:</strong> Quiz 4 câu theo bài nằm ở trang quiz của từng module trên site khóa học; việc đối chiếu và tích hợp vào từng chương trong repo gốc chưa hoàn tất (<code>CONTENT_PENDING</code>).</li><li><strong>10 câu hỏi tổng hợp cuối khóa:</strong> Kiểm tra khả năng kết nối toàn bộ workflow từ DMP đến lưu trữ và chia sẻ an toàn.</li><li><strong>Mục tiêu tự đánh giá khuyến nghị:</strong> $$\\text{Mục tiêu tự đánh giá khuyến nghị:} \\quad \\text{Đúng} \\ge 24/34 \\text{ câu } \\quad \\text{và đúng} \\ge 2/3 \\text{ câu Q1–Q3 trong Quiz Tổng hợp};\\ \\text{không ai ghi lại kết quả.}$$ <em>(Ba câu Q1–Q3 kiểm tra mạch logic cốt lõi của quy trình 7 giai đoạn.)</em></li></ul><h3 id="_4-2-thang-tu-đoi-chieu-bai-thuc-hanh-self-assessment-rubrics" tabindex="-1">4.2. Thang Tự đối chiếu Bài thực hành (Self-Assessment Rubrics) <a class="header-anchor" href="#_4-2-thang-tu-đoi-chieu-bai-thuc-hanh-self-assessment-rubrics" aria-label="Permalink to &quot;4.2. Thang Tự đối chiếu Bài thực hành (Self-Assessment Rubrics)&quot;">​</a></h3><p>Mỗi bài lab đều đi kèm bảng tiêu chí tự chấm /20 điểm. Thang điểm này <strong>chỉ phục vụ mục đích tự đối chiếu kỹ năng</strong> của người học:</p><ul><li><strong>$\\ge 16/20$:</strong> Mức gợi ý để tự đối chiếu; không thay thế đánh giá năng lực trong một nghiên cứu thực tế.</li><li><strong>$12 - 15/20$:</strong> Đạt yêu cầu cơ bản, cần xem lại phần giải thích lý thuyết liên quan.</li><li><strong>$&lt; 12/20$:</strong> Nên thực hành lại bài lab theo từng bước hướng dẫn.</li></ul><h3 id="_4-3-bai-tap-capstone-tu-đanh-gia-cuoi-khoa" tabindex="-1">4.3. Bài tập Capstone Tự Đánh giá Cuối khóa <a class="header-anchor" href="#_4-3-bai-tap-capstone-tu-đanh-gia-cuoi-khoa" aria-label="Permalink to &quot;4.3. Bài tập Capstone Tự Đánh giá Cuối khóa&quot;">​</a></h3><ul><li><strong>Nhiệm vụ:</strong> Người học đóng vai trò Data Steward, tự thiết kế trọn gói một bộ hồ sơ RDM cho một nghiên cứu giả định tại bệnh viện (ví dụ: nghiên cứu da liễu, tim mạch hoặc nội tiết).</li><li><strong>Sản phẩm tự hoàn thiện:</strong><ol><li>Bản DMSP theo mẫu NIH hiện hành (7 yếu tố) hoặc Horizon Europe, tham khảo <code>/course/book/appendices/funder-templates</code>.</li><li>Bảng mô tả cấu trúc biến số eCRF / Data Dictionary.</li><li>Kế hoạch đảm bảo chất lượng, xử lý dữ liệu khuyết và khử định danh.</li><li>Kế hoạch chia sẻ dữ liệu FAIR và đảm bảo chuẩn sẵn sàng cho AI.</li></ol></li><li><strong>Tự nghiệm thu:</strong> Người học tự đối chiếu sản phẩm của mình với <strong>Checklist Capstone 1 trang</strong> có sẵn ở cuối khóa học.</li></ul><hr><h2 id="_5-tai-lieu-nen-tang-va-can-cu-phap-ly" tabindex="-1">5. TÀI LIỆU NỀN TẢNG VÀ CĂN CỨ PHÁP LÝ <a class="header-anchor" href="#_5-tai-lieu-nen-tang-va-can-cu-phap-ly" aria-label="Permalink to &quot;5. TÀI LIỆU NỀN TẢNG VÀ CĂN CỨ PHÁP LÝ&quot;">​</a></h2><p>Khóa học sử dụng <code>references.bib</code>, hiện có 103 mục lõi và các mục riêng của chương (tổng 115 mục trong file); trạng thái gồm <code>VERIFIED_UNAUDITED</code>/<code>BIB_PENDING</code>, chưa audit độc lập:</p><ul><li><strong>Đọc thêm:</strong><ol><li><em>Wilkinson et al. (2016).</em> The FAIR Guiding Principles for scientific data management and stewardship. <em>Sci Data</em>, 3, 160018. <a href="/biomedical-rdm-course/course/book/references.html#ref-12">12</a></li><li><em>International Council for Harmonisation (ICH).</em> (2025). <em>ICH E6(R3) Guideline for Good Clinical Practice — Step 4</em>. <a href="/biomedical-rdm-course/course/book/references.html#ref-4">4</a></li><li><em>Baker, M. (2016).</em> 1,500 scientists lift the lid on reproducibility. <em>Nature</em>, 533(7604), 452–454. <a href="/biomedical-rdm-course/course/book/references.html#ref-33">33</a></li><li><em>National Institutes of Health.</em> (2020/2026). NIH Data Management and Sharing Policy (NOT-OD-21-013, NOT-OD-21-014, NOT-OD-26-046). <a href="/biomedical-rdm-course/course/book/references.html#ref-5">5</a>, <a href="/biomedical-rdm-course/course/book/references.html#ref-7">7</a>, <a href="/biomedical-rdm-course/course/book/references.html#ref-8">8</a></li><li><em>Weiskopf, N. G., &amp; Weng, C. (2013).</em> Methods and dimensions of electronic health record data quality assessment. <em>J Am Med Inform Assoc</em>, 20(1), 144–151. <a href="/biomedical-rdm-course/course/book/references.html#ref-28">28</a></li></ol></li><li><strong>Căn cứ pháp lý hiện hành tại Việt Nam:</strong> Chi tiết, URL, ngày kiểm và trạng thái kiểm chứng được cập nhật tại <a href="/biomedical-rdm-course/course/book/appendices/legal.html">phụ lục pháp lý</a>, chốt ngày 21/11/2026. Các văn bản được nêu ở đó gồm Luật Bảo vệ dữ liệu cá nhân, Nghị định 356/2025/NĐ-CP, Thông tư 13/2025/TT-BYT, Thông tư 33/2025/TT-BYT và Thông tư 50/2025/TT-BYT; không suy rộng nội dung ngoài phụ lục.</li></ul>`,33)])])}const m=n(a,[["render",l]]);export{d as __pageData,m as default};
